'use strict';
const form=document.querySelector('#spec'),status=document.querySelector('#status'),specKey='task-author-stage2-v1',ideaKey='task-author-stage1-v1';
const ownChecks=['isolation','offline','services','authorOwned','manual'];
function read(key){try{return JSON.parse(localStorage.getItem(key)||'null');}catch{return null;}}
function context(){const idea=read(ideaKey);const d=idea?.data;document.querySelector('#context').textContent=d?`${d.title||'Untitled idea'}\nDomain: ${d.domain||'not set'} / ${d.field||'not set'}\nProblem: ${d.problem||'not set'}\nGround truth: ${d.truthSource||'not set'}\nStage 1 is self-reported and has not been approved.`:'No stage 1 draft found in this browser/origin. Return to Idea & eligibility or import a workspace backup.';}
function collect(){const d={};for(const e of form.elements)if(e.name)d[e.name]=e.type==='checkbox'?e.checked:e.value;return d;}
function suffix(){const n=form.elements.agentSeconds.value;document.querySelector('#suffix').textContent=`You have ${n||'N'} seconds to complete this task. Do not cheat by using online solutions or hints specific to this task.`;}
function hydrate(d){if(!d||typeof d!=='object'||Array.isArray(d))throw Error('Invalid specification');form.reset();for(const e of form.elements)if(e.name&&Object.hasOwn(d,e.name)){if(e.type==='checkbox')e.checked=d[e.name]===true;else if(typeof d[e.name]==='string')e.value=d[e.name];}suffix();}
function save(){try{localStorage.setItem(specKey,JSON.stringify({schema:'task-author.spec.v1',savedAt:new Date().toISOString(),data:collect()}));status.textContent='Specification saved in this browser';}catch{status.textContent='Storage unavailable. Export a workspace backup.';}}
function changed(){suffix();save();document.querySelector('#review').hidden=true;}
form.addEventListener('input',changed);form.addEventListener('change',changed);document.querySelector('#save').onclick=save;
function validate(){const problems=[],pending=[];for(const e of form.elements)if((e.required&&!e.value.trim())||(e.name&&e.value&&!e.checkValidity()))problems.push('Complete or correct: '+e.closest('label').childNodes[0].textContent.trim()+'.');for(const k of ownChecks)if(!form.elements[k].checked)problems.push('Declaration missing: '+form.elements[k].parentElement.textContent.trim());const d=collect();const paths=d.artifacts.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(paths.some(x=>!/^\/(?!\/)[^\s\\]+$/.test(x)||x.split('/').some(p=>p==='..'||p==='.')||x.endsWith('/')))problems.push('Artifacts must be absolute Linux file paths without whitespace or traversal components.');if(new Set(paths).size!==paths.length)problems.push('Remove duplicate artifact paths.');for(const p of paths)if(!d.instruction.includes(p))problems.push('Instruction does not name output path: '+p);if(/^\s{0,3}#{1,6}\s/m.test(d.instruction))problems.push('Rule conflict: Markdown headings are prohibited in instruction.md.');if(/^\s*(?:\d+[.)]|[-*+])\s/m.test(d.instruction))problems.push('Instruction contains a list. Review and write plain prose without a prescribed step checklist.');const ending=`You have ${d.agentSeconds} seconds to complete this task. Do not cheat by using online solutions or hints specific to this task.`;const normalized=d.instruction.replace(/\r\n/g,'\n');if(!(normalized.endsWith('\n\n'+ending)||normalized.endsWith('\n\n'+ending+'\n')))problems.push('Instruction must end with a blank line and the exact required sentence matching the integer agent timeout, with at most one final newline.');if(d.exceptions.trim())problems.push('Proposed exception recorded: stop dependent work and discuss the specific conflict for explicit user permission.');const idea=read(ideaKey)?.data;if(!idea)pending.push('Stage 1 draft is missing.');else{if(idea.truthSource!=='independent')problems.push('Stage 1 ground truth independence is not established or conflicts with the rule.');if(idea.knownConflict==='yes')problems.push('Stage 1 records a rule conflict requiring discussion.');if(!idea.authorship||!idea.realWork||!idea.novel||!idea.fair||!idea.internet||!idea.isolation||!idea.independent)pending.push('Stage 1 declarations are incomplete.');}
if(!d.oracleSeconds)pending.push('Oracle runtime has not been recorded. Measure it in stage 4 and reassess the agent budget.');else if(+d.agentSeconds<=+d.oracleSeconds)problems.push('Agent budget does not exceed the measured oracle duration; plan several times that duration.');else pending.push(`Agent/oracle time ratio: ${(+d.agentSeconds/+d.oracleSeconds).toFixed(2)}. Manually assess whether this gives several times the solution runtime.`);if(!d.measuredVerifier)pending.push('Verifier runtime has not been recorded.');else if(+d.measuredVerifier>+d.verifierSeconds)problems.push('Measured verifier duration exceeds its planned timeout.');pending.push('Difficulty solve-band conflict remains unresolved. Scientific correctness, originality, prose authorship, and verifier robustness require independent review.');return {problems,pending};}
form.onsubmit=e=>{e.preventDefault();save();const {problems,pending}=validate(),out=document.querySelector('#review');out.replaceChildren();const h=document.createElement('h2');h.textContent=problems.length?'Specification needs attention':'Structural checks passed · review still required';out.append(h);for(const [title,items] of [['Required corrections',problems],['Pending evidence and manual review',pending]]){if(!items.length)continue;const sub=document.createElement('h3');sub.textContent=title;out.append(sub);const ul=document.createElement('ul');for(const msg of items){const li=document.createElement('li');li.textContent=msg;ul.append(li);}out.append(ul);}out.hidden=false;out.scrollIntoView({behavior:'smooth'});};
document.querySelector('#export').onclick=()=>{save();const payload={schema:'task-author.workspace.v1',exportedAt:new Date().toISOString(),idea:read(ideaKey),specification:read(specKey),ruleStatus:{difficultyBand:'unresolved',acceptance:'not-assessed'}};const u=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='task-author-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
document.querySelector('#import').onclick=()=>document.querySelector('#file').click();document.querySelector('#file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('Backup exceeds 2 MB');const p=JSON.parse(await f.text());if(p.schema!=='task-author.workspace.v1'||p.specification?.schema!=='task-author.spec.v1'||!p.specification.data||typeof p.specification.data!=='object'||Array.isArray(p.specification.data))throw Error('Unrecognized workspace backup');if(p.idea&&(p.idea.schema!=='task-author.idea.v1'||!p.idea.data||typeof p.idea.data!=='object'||Array.isArray(p.idea.data)))throw Error('Invalid idea backup');hydrate(p.specification.data);save();if(p.idea)localStorage.setItem(ideaKey,JSON.stringify(p.idea));context();document.querySelector('#review').hidden=true;}catch(err){status.textContent='Import failed: '+err.message;}e.target.value='';};
const saved=read(specKey);if(saved?.schema==='task-author.spec.v1'){try{hydrate(saved.data);status.textContent='Saved specification restored';}catch{status.textContent='Saved specification could not be restored.';}}suffix();context();
